l` ), union_data AS ( SELECT * FROM app_data UNION ALL SELECT * FROM web_data ) SELECT c.event_date, c.DateAsInteger, c.DateNumber, c.Year, c.MonthNumber, c.YearMonthNumber, c.YearMonthShort, c.MonthNameShort, c.MonthNameLong, c.DayOfWeekNumber, c.DayOfWeek, c.DayOfWeekShort, c.Quarter, c.YearQuarter, c.WeekPeriod, u.Channel, u.Sessions, u.Add_to_Cart, u.S2C, u.Orders, u.Conversion, u.App_Share_Orders, u.App_Share_Revenue, u.Gross_Sales, u.Net_Sales, u.AOV, u.Cart_Cr, u.Cart_to_Checkout, u.Checkout_Started, u.Address_Landed, u.Payment_Step_Reached, u.Payment_Method_Selected, u.Sessions_Converted, u.Avg_Conversion_Pct, u.Address_Pct, u.Payment_Step_Pct, u.Payment_Method_Pct, u.Sessions_Cvr_Pct, u.Installs_Android, u.Installs_iOS, u.DAU, u.WAU, u.MAU, u.Android_Users, u.iOS_Users, u.Abandone_Checkout FROM calendar c LEFT JOIN union_data u ON c.event_date = u.event_date",
